    }
    if (reduced_symmetry != NULL) {
        sym_free_symmetry(reduced_symmetry);
    }
    if (spacegroup != NULL) {
        free(spacegroup);
    }
    return 0;
}

/*
 * Change symmetry coordinates from lattice L to its Delaunay-reduced basis
 * L' = L P. Fractional coordinates obey x = P x', hence
 * (R', t') = (P^-1 R P, P^-1 t).
 */
static Symmetry *get_delaunay_reduced_symmetry(
    double reduced_lattice[3][3], Symmetry const *symmetry,
    double const lattice[3][3], double const symprec) {
    int i, j;
    int change_of_basis_int[3][3], change_of_basis_inv_int[3][3];
    double original_lattice[3][3], reduced_lattice_inv[3][3];
    double change_of_basis[3][3];
    double change_of_basis_inv[3][3], rotation[3][3];
    Symmetry *reduced_symmetry;

    reduced_symmetry = NULL;

    /* reduced_lattice and lattice are allowed to alias. */
    mat_copy_matrix_d3(original_lattice, lattice);
    if (!del_delaunay_reduce(reduced_lattice, original_lattice, symprec)) {
        goto err;
    }
    if (!mat_inverse_matrix_d3(reduced_lattice_inv, reduced_lattice,
                               symprec)) {
        goto err;
    }
    /*
     * First recover P^-1 = L'^-1 L. This direction is numerically stable even
     * when the input basis L = L' P^-1 has large integer coefficients.
     */
    mat_multiply_matrix_d3(change_of_basis_inv, reduced_lattice_inv,
                           original_lattice);
    mat_cast_matrix_3d_to_3i(change_of_basis_inv_int, change_of_basis_inv);
    if (!mat_check_identity_matrix_id3(change_of_basis_inv_int,
                                       change_of_basis_inv, 1e-8) ||
        !get_inverse_unimodular_matrix(change_of_basis_int,
                                       change_of_basis_inv_int)) {
        goto err;
    }
    mat_cast_matrix_3i_to_3d(change_of_basis, change_of_basis_int);
    mat_cast_matrix_3i_to_3d(change_of_basis_inv,
                            change_of_basis_inv_int);

    if ((reduced_symmetry = sym_alloc_symmetry(symmetry->size)) == NULL) {
        goto err;
    }
    for (i = 0; i < symmetry->size; i++) {
        mat_cast_matrix_3i_to_3d(rotation, symmetry->rot[i]);
        if (!mat_get_similar_matrix_d3(rotation, rotation, change_of_basis,
                                       0)) {
            goto err;
        }
        mat_cast_matrix_3d_to_3i(reduced_symmetry->rot[i], rotation);
        if (!mat_check_identity_matrix_id3(reduced_symmetry->rot[i], rotation,
                                           1e-8)) {
            goto err;
        }
        mat_multiply_matrix_vector_d3(reduced_symmetry->trans[i],
                                      change_of_basis_inv,
                                      symmetry->trans[i]);
        for (j = 0; j < 3; j++) {
            reduced_symmetry->trans[i][j] =
                mat_Dmod1(reduced_symmetry->trans[i][j]);
        }
    }

    return reduced_symmetry;

err:
    if (reduced_symmetry != NULL) {
        sym_free_symmetry(reduced_symmetry);
    }
    return NULL;
}

/* Return the exact inverse of a 3x3 integer matrix with determinant +/-1. */
static int get_inverse_unimodular_matrix(int inverse[3][3],
                                         int const matrix[3][3]) {
    int const det = mat_get_determinant_i3(matrix);

    if (abs(det) != 1) {
        return 0;
    }

    inverse[0][0] =
        (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1]) / det;
    inverse[0][1] =
        (matrix[0][2] * matrix[2][1] - matrix[0][1] * matrix[2][2]) / det;
    inverse[0][2] =
        (matrix[0][1] * matrix[1][2] - matrix[0][2] * matrix[1][1]) / det;
    inverse[1][0] =
        (matrix[1][2] * matrix[2][0] - matrix[1][0] * matrix[2][2]) / det;
    inverse[1][1] =
        (matrix[0][0] * matrix[2][2] - matrix[0][2] * matrix[2][0]) / det;
    inverse[1][2] =
        (matrix[0][2] * matrix[1][0] - matrix[0][0] * matrix[1][2]) / det;
    inverse[2][0] =
        (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0]) / det;
    inverse[2][1] =
        (matrix[0][1] * matrix[2][0] - matrix[0][0] * matrix[2][1]) / det;
    inverse[2][2] =
        (matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]) / det;

    return 1;
}
